<div class="topline"><span><?= e(t('TURN EXPERIENCE INTO PROGRESS')) ?></span><span><?= e(t('Notice. Learn. Act.')) ?></span></div><header class="page-header"><div><h1><?= e(t('Make the lesson count.')) ?></h1><p class="muted"><?= e(t('A setback becomes useful when it changes your next step.')) ?></p></div><a class="btn" href="/review"><?= e(t('Weekly review →')) ?></a></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<?php foreach ($repeated as $pattern): ?><div class="notice warning"><strong><?= e(t('Recurring pattern ·')) ?> <?= e($pattern['area']) ?></strong><br><?= e($pattern['n']) ?> <?= e(t('failures logged in 90 days. Review the root causes and try a different action.')) ?></div><?php endforeach; ?>
<div class="two-col"><section class="card"><h2><?= e(t('Log a failure. Find a way forward.')) ?></h2><form class="stack" method="post" action="/lessons"><?= csrf_field() ?><label><?= e(t('Area')) ?><select name="area"><?php foreach (LessonService::AREAS as $area): ?><option><?= e($area) ?></option><?php endforeach; ?></select></label><label><?= e(t('What happened?')) ?><textarea name="what_happened" maxlength="3000" rows="3" required></textarea></label><label><?= e(t('Root cause')) ?><textarea name="root_cause" maxlength="3000" rows="2" placeholder="<?= e(t('What made this happen?')) ?>"></textarea></label><label><?= e(t('What did you learn?')) ?><textarea name="lesson" maxlength="3000" rows="2"></textarea></label><label><?= e(t('Next action')) ?><input name="action" maxlength="200" placeholder="<?= e(t('A specific step — becomes a task')) ?>"></label><label><?= e(t('Action due date')) ?><input type="date" name="due"></label><button><?= e(t('Save lesson')) ?></button></form></section>
<section class="card"><h2><?= e(t('Your next actions')) ?></h2><?php require __DIR__.'/tasks.php'; ?><h3><?= e(t('Add a task')) ?></h3><form class="stack" method="post" action="/tasks"><?= csrf_field() ?><label><?= e(t('Task')) ?><input name="title" maxlength="200" required></label><label><?= e(t('Due date (optional)')) ?><input type="date" name="due"></label><button class="secondary"><?= e(t('Add task')) ?></button></form><?php if ($completed): ?><details class="completed"><summary><?= e(t('Completed tasks (latest 30)')) ?></summary><?php foreach ($completed as $t): ?><div class="task-row"><span><?= e($t['title']) ?></span><form method="post" action="/tasks/<?= e($t['id']) ?>/reopen"><?= csrf_field() ?><button class="quiet"><?= e(t('Reopen')) ?></button></form></div><?php endforeach; ?></details><?php endif; ?></section></div>
<section class="card"><h2><?= e(t('Your lesson journal')) ?></h2><p class="muted"><?= e(t('Open → applied when the action is done → verified when you confirm the failure has not repeated.')) ?></p><?php if (!$lessons): ?><div class="empty"><h3><?= e(t('Your experience belongs here.')) ?></h3><p><?= e(t('Log your first lesson above.')) ?></p></div><?php else: foreach ($lessons as $l): ?><article class="lesson-entry"><div class="section-heading"><span class="badge"><?= e($l['area']) ?> · <?= e(substr($l['created_at'],0,10)) ?></span><span class="muted"><?= e(ucfirst($l['status'])) ?></span></div><h3><?= e($l['what_happened']) ?></h3><dl class="lesson-detail"><dt><?= e(t('Root cause')) ?></dt><dd><?= e($l['root_cause'] ?: t('Not recorded')) ?></dd><dt><?= e(t('Lesson')) ?></dt><dd><?= e($l['lesson'] ?: t('Not recorded')) ?></dd><dt><?= e(t('Action')) ?></dt><dd><?= e($l['action'] ?: t('No action added')) ?><?= $l['task_status'] ? ' · Task '.e($l['task_status']) : '' ?></dd></dl><div class="section-heading"><form class="inline" method="post" action="/lessons/<?= e($l['id']) ?>/status"><?= csrf_field() ?><select name="status" aria-label="Status for lesson <?= e($l['id']) ?>"><?php foreach (['open','applied','verified'] as $status): ?><option value="<?= e($status) ?>" <?= $l['status']===$status ? 'selected' : '' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select><button class="secondary"><?= e(t('Update')) ?></button></form><form method="post" action="/lessons/<?= e($l['id']) ?>/delete" data-confirm="Delete this lesson and its linked action task?"><?= csrf_field() ?><button class="delete"><?= e(t('Delete lesson')) ?></button></form></div></article><?php endforeach; endif; ?></section>
